# Source of truth for guess_picture items (SVG bodies on a 100x100 canvas).
import math
def poly(n, r=38, cx=50, cy=52, rot=-90, star=False, inner=0.45):
    pts=[]
    k = n*2 if star else n
    for i in range(k):
        a=math.radians(rot+360*i/k); rr = r if (not star or i%2==0) else r*inner
        pts.append("%.1f,%.1f"%(cx+rr*math.cos(a), cy+rr*math.sin(a)))
    return '<polygon points="%s" fill="{F}"/>'%" ".join(pts)
